import { isIPv4, isIPv6 } from 'net';

function ipv4ToInt(ip) {
  const parts = ip.split('.').map(Number);
  return parts[0] * 16777216 + parts[1] * 65536 + parts[2] * 256 + parts[3];
}

export default (ip) => {
  // Handle special cases first
  if (ip === '::' || ip === '::1') return true;

  // Check IPv4-mapped IPv6 addresses (::ffff:x.x.x.x)
  if (ip.toLowerCase().startsWith('::ffff:')) {
    const ipv4Part = ip.substring(7);
    if (isIPv4(ipv4Part)) ip = ipv4Part;
  }

  // Validate using Node.js net module capabilities
  if (isIPv4(ip)) {
    const ipNum = ipv4ToInt(ip);
    // IANA reserved ranges
    return (
      (ipNum >= 0x00000000 && ipNum <= 0x00FFFFFF) || // 0.0.0.0/8
      (ipNum >= 0x0A000000 && ipNum <= 0x0AFFFFFF) || // 10.0.0.0/8
      (ipNum >= 0x64400000 && ipNum <= 0x647FFFFF) || // 100.64.0.0/10
      (ipNum >= 0x7F000000 && ipNum <= 0x7FFFFFFF) || // 127.0.0.0/8
      (ipNum >= 0xA9FE0000 && ipNum <= 0xA9FEFFFF) || // 169.254.0.0/16
      (ipNum >= 0xAC100000 && ipNum <= 0xAC1FFFFF) || // 172.16.0.0/12
      (ipNum >= 0xC0000000 && ipNum <= 0xC00000FF) || // 192.0.0.0/24
      (ipNum >= 0xC0A80000 && ipNum <= 0xC0A8FFFF) || // 192.168.0.0/16
      (ipNum >= 0xC6120000 && ipNum <= 0xC613FFFF) || // 198.18.0.0/15
      (ipNum >= 0xE0000000 && ipNum <= 0xFFFFFFFF)   // 224.0.0.0+
    );
  } 

  if (isIPv6(ip)) {
    // Normalize and check IPv6 ranges
    const firstBlock = ip.split(':')[0].toLowerCase();
    return (
      firstBlock.startsWith('fc') || // Unique-local
      firstBlock.startsWith('fd') || // Unique-local
      firstBlock.startsWith('fe8') || // Link-local
      firstBlock.startsWith('fe9') ||
      firstBlock.startsWith('fea') ||
      firstBlock.startsWith('feb') ||
      firstBlock === 'ff00' // Multicast
    );
  }

  // Fallback for invalid formats
  return false;
};

