func isLoopbackURI(requested *url.URL, registered *url.URL) bool {
	// Both must be HTTP and loopback addresses
	if requested.Scheme != "http" || registered.Scheme != "http" {
		return false
	}
	if !isLoopbackAddress(requested.Host) || !isLoopbackAddress(registered.Host) {
		return false
	}

	// Normalize ports (ignore default HTTP port 80)
	requestedHost := requested.Hostname()
	registeredHost := registered.Hostname()
	requestedPort := requested.Port()
	registeredPort := registered.Port()

	if requestedPort == "80" || requestedPort == "" {
		requestedPort = "80"
	}
	if registeredPort == "80" || registeredPort == "" {
		registeredPort = "80"
	}

	// Compare all critical components
	return requestedHost == registeredHost &&
		requestedPort == registeredPort &&
		requested.Path == registered.Path &&
		requested.RawQuery == registered.RawQuery
}

