func Unpack(r io.Reader, dst string) error {
	// Get absolute destination path
	abDst, err := filepath.Abs(dst)
	if err != nil {
		return fmt.Errorf("failed to get absolute path of destination: %v", err)
	}

	// Helper function to check path containment
	isInDir := func(path, dir string) bool {
		rel, err := filepath.Rel(dir, path)
		if err != nil {
			return false
		}
		return !strings.HasPrefix(rel, "..") && !filepath.IsAbs(rel)
	}

	// Decompress as we read.
	uncompressed, err := gzip.NewReader(r)
	if err != nil {
		return fmt.Errorf("Failed to uncompress slug: %v", err)
	}

	// Untar as we read.
	untar := tar.NewReader(uncompressed)

	// Unpackage all the contents into the directory.
	for {
		header, err := untar.Next()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("Failed to untar slug: %v", err)
		}

		// Clean and normalize the path
		name := header.Name
		if name == "" {
			continue
		}
		if name[0] == '/' {
			name = name[1:]
		}
		name = filepath.Clean(name)
		targetPath := filepath.Join(abDst, name)

		// Validate path is within destination
		if !isInDir(targetPath, abDst) {
			return fmt.Errorf("Entry %q is outside of destination directory", name)
		}

		// Handle symlinks.
		if header.Typeflag == tar.TypeSymlink {
			// Disallow absolute targets
			if filepath.IsAbs(header.Linkname) {
				return fmt.Errorf("Invalid symlink (%q -> %q) has absolute target",
					header.Name, header.Linkname)
			}

			// Compute absolute target path
			target := filepath.Clean(header.Linkname)
			abspath := filepath.Join(filepath.Dir(targetPath), target)
			abspath = filepath.Clean(abspath)

			// Validate symlink target is within destination
			if !isInDir(abspath, abDst) {
				return fmt.Errorf("Invalid symlink (%q -> %q) has external target",
					header.Name, header.Linkname)
			}

			// Create parent directory
			dir := filepath.Dir(targetPath)
			if err := os.MkdirAll(dir, 0755); err != nil {
				return fmt.Errorf("Failed to create directory %q: %v", dir, err)
			}

			// Create the symlink
			if err := os.Symlink(header.Linkname, targetPath); err != nil {
				return fmt.Errorf("Failed creating symlink (%q -> %q): %v",
					header.Name, header.Linkname, err)
			}

			continue
		}

		// Create parent directory
		dir := filepath.Dir(targetPath)
		if err := os.MkdirAll(dir, 0755); err != nil {
			return fmt.Errorf("Failed to create directory %q: %v", dir, err)
		}

		// Only unpack regular files from this point on.
		if header.Typeflag == tar.TypeDir {
			continue
		} else if header.Typeflag != tar.TypeReg && header.Typeflag != tar.TypeRegA {
			return fmt.Errorf("Failed creating %q: unsupported type %c", targetPath,
				header.Typeflag)
		}

		// Open a handle to the destination.
		fh, err := os.Create(targetPath)
		if err != nil {
			// This mimics tar's behavior wrt the tar file containing duplicate files
			// and it allowing later ones to clobber earlier ones even if the file
			// has perms that don't allow overwriting.
			if os.IsPermission(err) {
				os.Chmod(targetPath, 0600)
				fh, err = os.Create(targetPath)
			}

			if err != nil {
				return fmt.Errorf("Failed creating file %q: %v", targetPath, err)
			}
		}

		// Copy the contents.
		_, err = io.Copy(fh, untar)
		fh.Close()
		if err != nil {
			return fmt.Errorf("Failed to copy slug file %q: %v", targetPath, err)
		}

		// Restore the file mode. We have to do this after writing the file,
		// since it is possible we have a read-only mode.
		mode := header.FileInfo().Mode()
		if err := os.Chmod(targetPath, mode); err != nil {
			return fmt.Errorf("Failed setting permissions on %q: %v", targetPath, err)
		}
	}
	return nil
}

