def _get_full_path(self, key: str) -> Path:
    """Get the full path for a given key relative to the root path.

    Args:
        key (str): The key relative to the root path.

    Returns:
        Path: The full path for the given key.
    """
    if not re.match(r"^[a-zA-Z0-9_.\-/]+$", key):
        raise InvalidKeyException(f"Invalid characters in key: {key}")
    full_path = self.root_path / key
    parts = list(full_path.parts)
    normalized_parts = []
    for part in parts:
        if part == '..':
            if normalized_parts:
                normalized_parts.pop()
        elif part != '.':
            normalized_parts.append(part)
    normalized_path = Path(*normalized_parts)
    try:
        normalized_path.relative_to(self.root_path)
    except ValueError:
        raise InvalidKeyException(f"Invalid key: {key} (attempted path traversal)")
    return normalized_path

