    const { execFileSync } = require('child_process');

    // Validate port input
    const portNum = parseInt(port, 10);
    if (isNaN(portNum) || portNum < 1 || portNum > 65535) {
        return;
    }

    let stdout;
    try {
        // Safe execution with parameterized arguments
        stdout = execFileSync('lsof', ['-t', '-i:' + portNum], { encoding: 'utf8' });
    } catch (e) {
        // Ignore errors (like original behavior)
        return;
    }

    const pids = stdout.trim().split('\n');
    for (let i = 0; i < pids.length; i++) {
        const pid = pids[i].trim();
        // Skip empty lines
        if (pid === '') continue;
        // Sanitize PID: must be digits only
        if (/^\d+$/.test(pid)) {
            try {
                execFileSync('kill', [pid]);
            } catch (e) {
                // Ignore kill errors
            }
        }
    }
};

