var server = http.createServer(function (req, res) {

    var uri = url.parse(req.url).pathname,
        basePath = path.resolve(root);

    // Secure path resolution
    let filename = path.join(basePath, uri.replace(/^(\/)/, ''));
    filename = path.resolve(filename);

    // Verify path containment
    if (!(filename === basePath || filename.startsWith(basePath + path.sep))) {
        if (wordy) console.log('Error 404 (Path Traversal Attempt)');
        res.writeHead(404, {'Content-Type': 'text/plain'});
        res.end('Error 404');
        return;
    }

    if (uri.charAt(uri.length - 1) === '/') {
        filename = path.join(filename, 'index.html');
    }

    if (wordy) console.log('GET:' + uri + ' -> ' + filename);

    fs.exists(filename, function (exists) {
        if (!exists) {
            if (wordy) console.log('Error 404');
            res.writeHead(404, {'Content-Type': 'text/plain'});
            res.end('Error 404');
            return;
        }

        // Use async filesystem operation
        fs.stat(filename, function(err, stats) {
            if (err) {
                if (wordy) console.log('Error 500');
                res.writeHead(500, {'Content-Type': 'text/plain'});
                res.end('Error 500');
                return;
