module.exports = function (packageName, { registry = '', timeout = null } = {}) {
    try {
        const { spawnSync } = require('child_process');
        const args = ['view', packageName, 'version'];
        if (registry) {
            args.push('--registry', registry);
        }
        const options = {
            stdio: ['pipe', 'pipe', 'ignore'],
            encoding: 'utf-8'
        };
        if (timeout) {
            options.timeout = timeout;
        }

        const child = spawnSync('npm', args, options);

        if (child.error) {
            throw child.error;
        }
        if (child.status !== 0) {
            throw new Error(`Command exited with code ${child.status}`);
        }
        if (child.signal) {
            throw new Error(`Command killed by signal ${child.signal}`);
        }

        const version = child.stdout;

        if (version) {
            return version.trim();
        } else {
            return null;
        }

    } catch(err) {
        return null;
    }
}

