module.exports = function whereis(name, cb) {
  const cp = require('child_process');

  // Validate input contains only safe characters
  if (!/^[\w\-\s.]+$/.test(name)) {
    return cb(new Error('Invalid name format'));
  }

  const commands = [];
  if (process.platform === 'win32') {
    commands.push({ cmd: 'where', args: [name] });
  } else {
    commands.push({ cmd: 'which', args: [name] });
    commands.push({ cmd: 'whereis', args: [name] });
  }

  let index = 0;
  const tryNext = () => {
    if (index >= commands.length) {
      return cb(new Error('Could not find ' + name + ' on your system'));
    }

    const { cmd, args } = commands[index++];
    cp.execFile(cmd, args, (error, stdout, stderr) => {
      if (error || stderr) {
        return tryNext();
      }

      let result = null;
      if (cmd === 'whereis') {
        const tokens = stdout.trim().split(/\s+/);
        if (tokens.length >= 2) {
          result = tokens[1];
        }
      } else {
        const lines = stdout.split('\n').filter(line => line.trim() !== '');
        if (lines.length > 0) {
          result = lines[0].trim();
        }
      }

      if (!result) {
        return tryNext();
      }

      // Platform-specific path validation
      if (process.platform !== 'win32') {
        if (result.charAt(0) !== '/') {
          return tryNext();
        }
      } else {
        if (result.indexOf('\\') === -1) {
          return tryNext();
        }
      }

      return cb(null, result);
    });
  };

  tryNext();
};

