    var safeEval = function(expr) {
      // Allow only numbers, operators, parentheses and spaces
      if (!/^[\d\s+\-*\/().]+$/.test(expr)) return NaN;

      // Tokenize and compute
      var tokens = expr.match(/[\d.]+|[+\-*\/()]/g) || [];
      var values = [];
      var ops = [];

      for (var i = 0; i < tokens.length; i++) {
        var token = tokens[i];
