	// Validate username contains only safe characters
	if !regexp.MustCompile(`^[a-zA-Z0-9_-]+$`).MatchString(username) {
		return fmt.Errorf("invalid username format")
	}

	configPath := filepath.Join(filepath.Dir(i.ExecPath), ".gotty")
	title := username + "@" + remoteIpAddr
	if remotePort != 22 {
		title = title + ":" + strconv.Itoa(remotePort)
	}

	// Build SSH command as direct arguments without shell
	sshArgs := []string{
		"-w",
		"-p", strconv.Itoa(listenPort),
		"--once",
		"--config", configPath,
		"--title-format", title,
		"ssh",
		"-t",
		"-l", username,  // Securely pass username as separate argument
		remoteIpAddr,
		"-p", strconv.Itoa(remotePort),
	}

	cmd := exec.Command(i.ExecPath, sshArgs...)
	cmd.Dir = filepath.Dir(i.ExecPath)
	cmd.Env = append(os.Environ(), "TERM=xterm")
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	go func() {
		cmd.Run()
		i.Destroy()
	}()
	i.tty = cmd
	i.AssignedPort = listenPort
	i.RemoteAddr = remoteIpAddr
	i.RemotePort = remotePort

	//Create a new proxy agent for this root
	path, err := url.Parse("http://127.0.0.1:" + strconv.Itoa(listenPort))
	if err != nil {
		return err
	}

	//Create new proxy objects to the proxy
	proxy := reverseproxy.NewReverseProxy(path)

	i.conn = proxy
	return nil
}

