func NewSortParameter(sort admin.Sort) (SortParameter, error) {
	// Validate sort key to prevent SQL injection
	valid := true
	if sort.Key == "" {
		valid = false
	} else {
		state := 0 // 0: start of part, 1: in part
		for _, c := range sort.Key {
			if state == 0 {
				// Start of part must be [a-zA-Z_]
				if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || c == '_' {
					state = 1
				} else {
					valid = false
					break
				}
			} else if state == 1 {
				if c == '.' {
					state = 0 // Next char must start new part
				} else if (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' {
					// Valid part character
				} else {
					valid = false
					break
				}
			}
		}
		// Final state must be in-part (not expecting new part)
		if state == 0 {
			valid = false
		}
	}

	if !valid {
		return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "invalid sort key: %s", sort.Key)
	}

	var gormOrderExpression string
	switch sort.Direction {
	case admin.Sort_DESCENDING:
		gormOrderExpression = fmt.Sprintf(gormDescending, sort.Key)
	case admin.Sort_ASCENDING:
		gormOrderExpression = fmt.Sprintf(gormAscending, sort.Key)
	default:
		return nil, errors.NewFlyteAdminErrorf(codes.InvalidArgument, "invalid sort order specified: %v", sort)
	}
	return &sortParamImpl{
		gormOrderExpression: gormOrderExpression,
	}, nil
}

