  const { filters, query: where, paginate } = this.filterQuery(params);

  // Validate $select to prevent raw SQL injection
  if (filters.$select) {
    if (!Array.isArray(filters.$select)) {
      return Promise.reject(new Error('$select must be an array'));
    }
    for (const item of filters.$select) {
      if (typeof item !== 'string') {
        return Promise.reject(new Error('$select array must contain only strings'));
      }
    }
  }

  const order = utils.getOrder(filters.$sort);

  // Strictly validate sequelize options
  let safeSequelizeOptions = {};
  if (params.sequelize) {
    const allowedSequelizeOptions = ['transaction', 'logging', 'benchmark', 'searchPath', 'include'];
    const disallowedKeys = [];

    Object.keys(params.sequelize).forEach(key => {
      if (allowedSequelizeOptions.includes(key)) {
        safeSequelizeOptions[key] = params.sequelize[key];
      } else {
        disallowedKeys.push(key);
      }
    });

    if (disallowedKeys.length > 0) {
      return Promise.reject(new Error(`Disallowed sequelize options: ${disallowedKeys.join(', ')}`));
    }
  }

  const q = Object.assign({
    where,
    order,
    limit: filters.$limit,
    offset: filters.$skip,
    raw: this.raw,
    distinct: true
  }, safeSequelizeOptions);

  if (filters.$select) {
    q.attributes = filters.$select;
  }

  const Model = this.applyScope(params);

  // Until Sequelize fix all the findAndCount issues, a few 'hacks' are needed to get the total count correct
  // Adding an empty include changes the way the count is done
  // See: https://github.com/sequelize/sequelize/blob/7e441a6a5ca44749acd3567b59b1d6ceb06ae64b/lib/model.js#L1780-L1782
  q.include = q.include || [];

  if (paginate && paginate.default) {
    return Model.findAndCountAll(q).then(result => {
      return {
        total: result.count,
        limit: filters.$limit,
        skip: filters.$skip || 0,
        data: result.rows
      };
    }).catch(utils.errorHandler);
  }

  return Model.findAll(q).catch(utils.errorHandler);
}

