getInfo: function () {
  var self = this;
  var getInfoCommand = this.constructGetInfoCommand();
  var execFile = require('child_process').execFile;
  var promise = new Promise(function (resolve, reject) {
    var index = getInfoCommand.indexOf(' \"');
    if (index === -1) {
      return reject(new Error("Invalid command format"));
    }
    var cmd = getInfoCommand.substring(0, index);
    var filePath = getInfoCommand.substring(index + 2, getInfoCommand.length - 1);
    execFile(cmd, [filePath], function (err, stdout, stderr) {
      if (err) {
        return reject({
          message: "Failed to get PDF'S information",
          error: err,
          stdout: stdout,
          stderr: stderr
        });
      }
      return resolve(self.parseGetInfoCommandOutput(stdout));
    });
  });
  return promise;
},

