module.exports = function (msg, silent) {
    const { execFileSync } = require('child_process');

    msg = makeDefault(msg);

    if (silent === undefined) {
        silent = true;
    }

    const disallowedChars = /[;|&$`()<>!]/;
    if (Array.isArray(msg)) {
        if (msg.some(m => disallowedChars.test(m))) {
            throw new Error('Invalid characters in commit message');
        }
    } else {
        if (disallowedChars.test(msg)) {
            throw new Error('Invalid characters in commit message');
        }
    }

    const args = ['commit', '--allow-empty', '--no-gpg-sign'];

    if (Array.isArray(msg)) {
        if (msg.length) {
            msg.forEach(function (m) {
                m = makeDefault(m);
                args.push('-m', m);
            });
        } else {
            args.push('-m', defaultMsg);
        }
    } else {
        args.push('-m', msg);
    }

    execFileSync('git', args, {
        stdio: silent ? 'ignore' : 'inherit'
    });
};

