export async function lookupWebFinger(
  resource: URL | string,
): Promise<ResourceDescriptor | null> {
  function isPrivateIP(ip: string): boolean {
    const parts = ip.split('.').map(part => parseInt(part, 10));
    if (parts.length === 4 && !parts.some(isNaN)) {
      // IPv4 private ranges
      if (parts[0] === 10) return true;
      if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
      if (parts[0] === 192 && parts[1] === 168) return true;
    }
    return false;
  }

  function isForbiddenHost(host: string): boolean {
    const hostLower = host.toLowerCase();
    // Block reserved domains
    if (hostLower === 'localhost') return true;
    if (hostLower.endsWith('.local')) return true;
    if (hostLower.endsWith('.internal')) return true;
    // Block private IPs
    if (isPrivateIP(hostLower)) return true;
    return false;
  }

  if (typeof resource === "string") resource = new URL(resource);
  let protocol = "https:";
  let server: string;
  if (resource.protocol === "acct:") {
    const atPos = resource.pathname.lastIndexOf("@");
    if (atPos < 0) return null;
    server = resource.pathname.substring(atPos + 1);
    if (server === "") return null;
  } else {
    protocol = resource.protocol;
    server = resource.host;
  }

  // Validate host security
  if (isForbiddenHost(server)) {
    logger.debug("Blocked forbidden host: {host}", { host: server });
    return null;
  }

  let url = new URL(`${protocol}//${server}/.well-known/webfinger`);
  url.searchParams.set("resource", resource.href);
  let redirected = 0;
  const visitedUrls = new Set<string>();
  visitedUrls.add(url.href);

  while (true) {
    logger.debug(
      "Fetching WebFinger resource descriptor from {url}...",
      { url: url.href },
    );

    // Validate URL host before request
    if (isForbiddenHost(url.hostname)) {
      logger.debug("Blocked forbidden host in URL: {host}", { host: url.hostname });
      return null;
    }

    let response: Response;
    try {
      response = await fetch(url, {
        headers: { Accept: "application/jrd+json" },
        redirect: "manual",
      });
    } catch (error) {
      logger.debug(
        "Failed to fetch WebFinger resource descriptor: {error}",
        { url: url.href, error },
      );
      return null;
    }

    // Handle redirection
    if (
      response.status >= 300 && response.status < 400 &&
      response.headers.has("Location")
    ) {
      redirected++;
      if (redirected >= MAX_REDIRECTION) {
        logger.error(
          "Too many redirections ({redirections}) while fetching WebFinger " +
            "resource descriptor.",
          { redirections: redirected },
        );
        return null;
      }

      const redirectedUrl = new URL(
        response.headers.get("Location")!,
        response.url == null || response.url === "" ? url : response.url,
      );

      // Immediately validate redirected host
      if (isForbiddenHost(redirectedUrl.hostname)) {
        logger.debug("Blocked forbidden host in redirected URL: {host}", { host: redirectedUrl.hostname });
        return null;
      }

      // Check for redirect loops using full URL
      if (visitedUrls.has(redirectedUrl.href)) {
        logger.error(
          "Redirect loop detected to URL: {url}",
          { url: redirectedUrl.href }
        );
        return null;
      }
      visitedUrls.add(redirectedUrl.href);

      // Protocol security
      if (redirectedUrl.protocol !== url.protocol) {
        logger.error(
          "Redirected to a different protocol ({protocol} to " +
            "{redirectedProtocol}) while fetching WebFinger resource " +
            "descriptor.",
          {
            protocol: url.protocol,
            redirectedProtocol: redirectedUrl.protocol,
          },
        );
        return null;
      }

      url = redirectedUrl;
      continue;
    }

    if (!response.ok) {
      logger.debug(
        "Failed to fetch WebFinger resource descriptor: {status} {statusText}.",
        {
          url: url.href,
          status: response.status,
          statusText: response.statusText,
        },
      );
      return null;
    }

    try {
      return await response.json() as ResourceDescriptor;
    } catch (e) {
      if (e instanceof SyntaxError) {
        logger.debug(
          "Failed to parse WebFinger resource descriptor as JSON: {error}",
          { error: e },
        );
        return null;
      }
      throw e;
    }
  }
}

