export async function lookupWebFinger(
  resource: URL | string,
): Promise<ResourceDescriptor | null> {
  class ForbiddenHostError extends Error {}

  function isPrivateIP(ip: string): boolean {
    // Handle IPv6 addresses
    if (ip.includes(':')) {
      if (ip === '::1') return true;
      const segments = ip.split(':');
      const firstSegment = segments[0] || '';
      if (firstSegment.startsWith('fc') || firstSegment.startsWith('fd')) return true;
      if (firstSegment === 'fe80') return true;
      return false;
    }

    // Handle IPv4 addresses
    const parts = ip.split('.').map(part => parseInt(part, 10));
    if (parts.length !== 4 || parts.some(isNaN)) return false;

    // Private ranges
    if (parts[0] === 10) return true;
    if (parts[0] === 172 && parts[1] >= 16 && parts[1] <= 31) return true;
    if (parts[0] === 192 && parts[1] === 168) return true;

    // Loopback
    if (parts[0] === 127) return true;

    // Link-local
    if (parts[0] === 169 && parts[1] === 254) return true;

    return false;
  }

  function isForbiddenHost(host: string): boolean {
    const hostLower = host.toLowerCase();
    if (hostLower === 'localhost') return true;
    if (hostLower.endsWith('.local')) return true;
    if (hostLower.endsWith('.internal')) return true;
    if (isPrivateIP(hostLower)) return true;
    return false;
  }

  if (typeof resource === "string") resource = new URL(resource);
  let protocol = "https:";
  let server: string;
  if (resource.protocol === "acct:") {
    const atPos = resource.pathname.lastIndexOf("@");
    if (atPos < 0) return null;
    server = resource.pathname.substring(atPos + 1);
    if (server === "") return null;
  } else {
    protocol = resource.protocol;
    server = resource.host;
  }

  // Validate host security
  if (isForbiddenHost(server)) {
    throw new ForbiddenHostError(`Blocked forbidden host: ${server}`);
  }

  let url = new URL(`${protocol}//${server}/.well-known/webfinger`);
  url.searchParams.set("resource", resource.href);
  let redirected = 0;
  const visitedUrls = new Set<string>();
  visitedUrls.add(url.href);

  while (true) {
    // Validate URL host before request
    if (isForbiddenHost(url.hostname)) {
      throw new ForbiddenHostError(`Blocked forbidden host in URL: ${url.hostname}`);
    }

    let response: Response;
    try {
      response = await fetch(url, {
        headers: { Accept: "application/jrd+json" },
        redirect: "manual",
      });
    } catch (error) {
      return null;
    }

    // Handle redirection
    if (
      response.status >= 300 && response.status < 400 &&
      response.headers.has("Location")
    ) {
      redirected++;
      if (redirected >= MAX_REDIRECTION) {
        return null;
