file.copy = function copy(srcpath, destpath, options) {
  options = options || {};
  if (!options.initialBase) {
    options.initialBase = path.resolve(destpath);
  }

  if (file.isDir(srcpath)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
    file.mkdir(destpath);
    // Iterate over all sub-files/dirs, recursing.
    fs.readdirSync(srcpath).forEach(function(filepath) {
      var nextSrc = path.join(srcpath, filepath);
      var nextDest = path.join(destpath, filepath);

      var resolvedNextDest = path.resolve(nextDest);
      var relativePath = path.relative(options.initialBase, resolvedNextDest);
      if (relativePath.startsWith('..')) {
        throw new Error('Path traversal detected: ' + nextDest + ' is outside the base directory');
      }

      copy(nextSrc, nextDest, options);
    });
  } else {
    // Copy a single file.
    var resolvedDest = path.resolve(destpath);
    var relativePath = path.relative(options.initialBase, resolvedDest);
    if (relativePath.startsWith('..')) {
      throw new Error('Path traversal detected: ' + destpath + ' is outside the base directory');
    }
    file._copy(srcpath, destpath, options);
  }
};

