  options = options || {};
  if (!options.initialBase) {
    options.initialBase = path.resolve(destpath);
  }
  var absoluteDest = path.resolve(destpath);
  if (absoluteDest !== options.initialBase && !absoluteDest.startsWith(options.initialBase + path.sep)) {
    throw new Error('Path traversal detected: ' + destpath + ' is outside the base directory');
  }

  if (file.isDir(srcpath)) {
    // Copy a directory, recursively.
    // Explicitly create new dest directory.
    file.mkdir(destpath);
    // Iterate over all sub-files/dirs, recursing.
    fs.readdirSync(srcpath).forEach(function(filepath) {
      copy(path.join(srcpath, filepath), path.join(destpath, filepath), options);
    });
  } else {
    // Copy a single file.
    file._copy(srcpath, destpath, options);
  }
};

