res.location = function location(url) {
  var loc = url;
  var urlParse = require('url').parse;

  // "back" is an alias for the referrer
  if (url === 'back') {
    loc = this.req.get('Referrer') || '/';
  }

  // Security fix: Validate redirect URLs with lenient parsing
  if (loc) {
    var allowedHosts = this.app.get('allowedRedirectHosts') || [];
    var safeDefault = '/';

    // Only validate if allow list exists
    if (allowedHosts.length > 0) {
      var parsed;

      try {
        // Use lenient URL parsing
        parsed = urlParse(loc);
        var hostname = parsed.hostname;

        // Validate host for absolute URLs
        if (hostname) {
          if (!allowedHosts.includes(hostname)) {
            loc = safeDefault;
            console.warn('Blocked open redirect to: ' + hostname);
          }
        }
        // Validate "back" alias referrer
        else if (url === 'back' && loc !== safeDefault) {
          var refParsed = urlParse(loc);
          if (refParsed.hostname && !allowedHosts.includes(refParsed.hostname)) {
            loc = safeDefault;
            console.warn('Blocked open redirect via Referrer: ' + refParsed.hostname);
          }
        }
      } catch (e) {
        // Maintain original URL on parse errors
        console.warn('URL parse warning: ' + e.message);
      }
    }
  }

  // Set location header with original URL format
  this.set('Location', loc);
  return this;
}

