func matchSignatures(signatures []oci.Signature, subject, subjectRegExp, issuer, issuerRegExp string, extensions map[string]string) error {
	if subject == "" && issuer == "" && len(extensions) == 0 {
		return nil
	}

	var errs []error
	for _, sig := range signatures {
		cert, err := sig.Cert()
		if err != nil {
			return fmt.Errorf("failed to read certificate: %w", err)
		}

		if cert == nil {
			return fmt.Errorf("certificate not found")
		}

		// Validate subjectRegExp if provided
		if subjectRegExp != "" {
			re, err := regexp.Compile(subjectRegExp)
			if err != nil {
				errs = append(errs, fmt.Errorf("invalid subject regex: %w", err))
				continue
			}
			if !re.MatchString(cert.Subject) {
				errs = append(errs, fmt.Errorf("subject does not match regex pattern"))
				continue
			}
		}

		// Validate issuerRegExp if provided
		if issuerRegExp != "" {
			re, err := regexp.Compile(issuerRegExp)
			if err != nil {
				errs = append(errs, fmt.Errorf("invalid issuer regex: %w", err))
				continue
			}
			if !re.MatchString(cert.Issuer) {
				errs = append(errs, fmt.Errorf("issuer does not match regex pattern"))
				continue
			}
		}

		if err := matchCertificateData(cert, subject, subjectRegExp, issuer, issuerRegExp, extensions); err != nil {
			errs = append(errs, err)
		} else {
			// only one signature certificate needs to match the required subject, issuer, and extensions
			return nil
		}
	}

	if len(errs) > 0 {
		err := multierr.Combine(errs...)
		return err
	}

	return fmt.Errorf("invalid signature")
}

