	funcMap["fail"] = func(msg string) (string, error) {
		if e.LintMode {
			// Don't fail when linting
			log.Printf("[INFO] Fail: %s", msg)
			return "", nil
		}
		return "", errors.New(warnWrap(msg))
	}

	// Conditionally enable getHostByName based on security settings
	if e.AllowDNSLookup {
		// Use original DNS-enabled implementation
	} else {
		funcMap["getHostByName"] = func(host string) (string, error) {
			return "", errors.New("getHostByName is disabled for security reasons. Enable via Engine.AllowDNSLookup")
		}
	}

	// If we are not linting and have a cluster connection, provide a Kubernetes-backed
	// implementation.
	if !e.LintMode && e.config != nil {
		funcMap["lookup"] = NewLookupFunction(e.config)
	}

	t.Funcs(funcMap)
}

