module.exports = p => {
  let root = ''
  let rest = p

  // Handle Windows UNC paths (starting with two backslashes)
  if (p.startsWith('\\')) {
    let pos = 2
    let count = 0
    // Find next two separators after initial backslashes
    while (count < 2 && pos < p.length) {
      let found = false
      // Scan for next separator (backslash or slash)
      for (let i = pos; i < p.length; i++) {
        if (p[i] === '\\' || p[i] === '/') {
          found = true
          pos = i + 1  // Continue after separator
          count++
          break
        }
      }
      if (!found) break
    }
    // If found two separators, split at last separator position
    if (count === 2) {
      root = p.substring(0, pos)
      rest = p.substring(pos)
    } else {
      root = p
      rest = ''
    }
  } 
  // Handle POSIX-style absolute paths
  else if (p.startsWith('/')) {
    let i = 0
    // Capture all consecutive slashes
    while (i < p.length && p[i] === '/') {
      i++
    }
    root = p.substring(0, i)
    rest = p.substring(i)
  }
  // Handle Windows drive paths
  else {
    const drivePattern = /[a-zA-Z]:[\\/]+/g
    let lastEnd = 0
    let match
    // Find all drive patterns (e.g., C:\, D:\\, etc.)
    while ((match = drivePattern.exec(p)) !== null) {
      lastEnd = drivePattern.lastIndex  // Track end position
    }
    // If drive patterns found, split at last pattern end
    if (lastEnd > 0) {
      root = p.substring(0, lastEnd)
      rest = p.substring(lastEnd)
    } 
    // Handle drive-relative paths (e.g., C:./file)
    else if (/^[a-zA-Z]:/.test(p)) {
      root = p.substring(0, 2)  // Capture drive prefix
      rest = p.substring(2)
    }
  }

  return [root, rest]
}

