const path = require('path');

module.exports = () => {
  // path => [function or Set]
  // A Set object means a directory reservation
  // A fn is a direct reservation on that path
  const queues = new Map();

  // fn => {paths:[path,...], dirs:[path, ...]}
  const reservations = new Map();

  // Comprehensive path normalization
  const normalizePath = (p) => {
    if (p === '') return '';

    // Normalize separators, unicode, and case
    let normalized = path.normalize(p)
      .normalize('NFC')
      .toLowerCase()
      .replace(/\\/g, '/');

    // Remove trailing slashes except for root paths
    if (normalized !== '/' && !/^[a-z]:\/$/.test(normalized)) {
      normalized = normalized.replace(/\/+$/, '');
    }

    return normalized;
  };

  // Calculate parent directories with normalization
  const getDirs = (filepath) => {
    const normalized = normalizePath(filepath);
    const tokens = normalized.split('/').filter(token => token !== '');
    const isAbsolute = normalized.startsWith('/') || /^[a-z]:\//.test(normalized);
    const isWindowsDrive = tokens.length > 0 && tokens[0].match(/^[a-z]:$/);

    let current = isWindowsDrive ? tokens[0] + '/' : (isAbsolute ? '/' : '');
    const dirs = isWindowsDrive ? [current] : (isAbsolute ? ['/'] : []);

    const startIndex = isWindowsDrive ? 1 : 0;
    for (let i = startIndex; i < tokens.length; i++) {
      if (i === tokens.length - 1) break;

      const token = tokens[i];
      current = current.endsWith('/') 
        ? `${current}${token}` 
        : `${current}/${token}`;

      // Ensure directory representation with trailing slash
      if (!current.endsWith('/')) {
        current += '/';
      }
      dirs.push(current);
    }

    return dirs;
  };

  // functions currently running
  const running = new Set();

  // return the queues for each path the function cares about
  // fn => {paths, dirs}
  const getQueues = fn => {
    const res = reservations.get(fn);
    /* istanbul ignore if - unpossible */
    if (!res)
      throw new Error('function does not have any path reservations');
    return {
      paths: res.paths.map(path => queues.get(path)),
      dirs: [...res.dirs].map(path => queues.get(path)),
    };
  };

  // check if fn is first in line for all its paths, and is
  // included in the first set for all its dir queues
  const check = fn => {
    const {paths, dirs} = getQueues(fn);
    return paths.every(q => q[0] === fn) &&
      dirs.every(q => q[0] instanceof Set && q[0].has(fn));
  };

  // run the function if it's first in line and not already running
  const run = fn => {
    if (running.has(fn) || !check(fn))
      return false;
    running.add(fn);
    fn(() => clear(fn));
    return true;
  };

  const clear = fn => {
    if (!running.has(fn))
      return false;

    const { paths, dirs } = reservations.get(fn);
    const next = new Set();

    paths.forEach(path => {
      const q = queues.get(path);
      assert.equal(q[0], fn);
      if (q.length === 1)
        queues.delete(path);
      else {
        q.shift();
        if (typeof q[0] === 'function')
          next.add(q[0]);
        else
          q[0].forEach(fn => next.add(fn));
      }
    });

    dirs.forEach(dir => {
      const q = queues.get(dir);
      assert(q[0] instanceof Set);
      if (q[0].size === 1 && q.length === 1) {
        queues.delete(dir);
      } else if (q[0].size === 1) {
        q.shift();
        next.add(q[0]);
      } else
        q[0].delete(fn);
    });
    running.delete(fn);

    next.forEach(fn => run(fn));
    return true;
  };

  const reserve = (paths, fn) => {
    // Apply comprehensive normalization
    paths = paths.map(p => normalizePath(p));

    const dirs = new Set(
      paths.map(path => getDirs(path)).reduce((a, b) => a.concat(b), [])
    );

    reservations.set(fn, {dirs, paths});

    paths.forEach(path => {
      const q = queues.get(path);
      if (!q) queues.set(path, [fn]);
      else q.push(fn);
    });

    dirs.forEach(dir => {
      const q = queues.get(dir);
      if (!q) queues.set(dir, [new Set([fn])]);
      else if (q[q.length-1] instanceof Set) q[q.length-1].add(fn);
      else q.push(new Set([fn]));
    });

    return run(fn);
  };

  return { check, reserve };
};

