func (p *GitLabProvider) EnrichSession(ctx context.Context, s *sessions.SessionState) error {
	// Retrieve user info
	userInfo, err := p.getUserInfo(ctx, s)
	if err != nil {
		return fmt.Errorf("failed to retrieve user info: %v", err)
	}

	// Check if email is verified
	if !p.AllowUnverifiedEmail && !userInfo.EmailVerified {
		return fmt.Errorf("user email is not verified")
	}

	s.User = userInfo.Username
	s.Email = userInfo.Email

	// Fetch and set the user's actual groups from GitLab
	if err := p.addGroupsToSession(ctx, s); err != nil {
		return fmt.Errorf("failed to retrieve groups: %v", err)
	}

	p.addProjectsToSession(ctx, s)

	return nil
}

// addGroupsToSession retrieves the user's actual groups from GitLab API
func (p *GitLabProvider) addGroupsToSession(ctx context.Context, s *sessions.SessionState) error {
	apiURL := p.ProtectedResource + "/api/v4/groups?per_page=100"
	req, err := http.NewRequestWithContext(ctx, "GET", apiURL, nil)
	if err != nil {
		return err
	}
	req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", s.AccessToken))

	var allGroups []string
	client := &http.Client{}

	for {
		resp, err := client.Do(req)
		if err != nil {
			return err
		}

		if resp.StatusCode != http.StatusOK {
			resp.Body.Close()
			return fmt.Errorf("failed to get groups: status %d", resp.StatusCode)
		}

		var groups []struct {
			FullPath string `json:"full_path"`
		}
		if err := json.NewDecoder(resp.Body).Decode(&groups); err != nil {
			resp.Body.Close()
			return err
		}
		resp.Body.Close()

		for _, group := range groups {
			allGroups = append(allGroups, fmt.Sprintf("group:%s", group.FullPath))
		}

		// Handle pagination
		nextPage := resp.Header.Get("X-Next-Page")
		if nextPage == "" {
			break
		}

		nextURL := fmt.Sprintf("%s&page=%s", apiURL, nextPage)
		req, err = http.NewRequestWithContext(ctx, "GET", nextURL, nil)
		if err != nil {
			return err
		}
		req.Header.Set("Authorization", fmt.Sprintf("Bearer %s", s.AccessToken))
	}

	s.Groups = allGroups
	return nil
}

