		if !ok {
			return nil, fmt.Errorf("invalid 'nbf' claim type")
		}
		if now < int64(nbfVal) {
			return nil, fmt.Errorf("token not yet valid")
		}
	}

	return verifyClaims(sets.NewString(append(r.allowedAudience, expectedAudience)...), claimsRaw)
}

