import os

class SecureStaticFileHandler(tornado.web.StaticFileHandler):
    def validate_absolute_path(self, root, absolute_path):
        if os.path.basename(absolute_path) == 'password.txt':
            raise tornado.web.HTTPError(404)
        return super().validate_absolute_path(root, absolute_path)

handlers = [(r"/", IndexHandler), (r"/login", LoginHandler),
            (r"/websocket", WebSocket),
            (r'/static/(.*)', SecureStaticFileHandler, {'path': ROOT})]

# Generate secure random cookie secret
