func (c *Client) httpGetRangeRequest(ctx context.Context, url string, start, end int64) (*http.Response, error) {
	req, err := c.newRequestWithURL(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}

	req.Header.Add("Range", fmt.Sprintf("bytes=%d-%d", start, end))

	// Create a copy of the HTTP client to avoid modifying the original
	httpClient := *c.HTTPClient

	// Preserve original redirect handling while adding credential protection
	originalCheckRedirect := httpClient.CheckRedirect
	httpClient.CheckRedirect = func(req *http.Request, via []*http.Request) error {
		// Remove Authorization header when redirected to different host
		if len(via) > 0 && via[len(via)-1].URL.Host != req.URL.Host {
			req.Header.Del("Authorization")
		}
		if originalCheckRedirect != nil {
			return originalCheckRedirect(req, via)
		}
		return nil
	}

	return httpClient.Do(req)
}

