func RequireSignedJWT(ctx context.Context, key []byte) error {
	if len(key) > 0 {
		rawjwt, ok := JWTFromGRPCRequest(ctx)
		if !ok {
			return status.Error(codes.Unauthenticated, "unauthenticated")
		}

		tok, err := jwt.ParseSigned(rawjwt)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		var claims jwt.Claims
		err = tok.Claims(key, &claims)
		if err != nil {
			return status.Errorf(codes.Unauthenticated, "invalid JWT: %v", err)
		}

		if claims.Expiry == nil || time.Now().After(claims.Expiry.Time()) {
			return status.Errorf(codes.Unauthenticated, "expired JWT")
		}

		expectedIssuer, ok := ctx.Value(issuerContextKey).(string)
		if !ok {
			return status.Error(codes.Unauthenticated, "issuer not provided in context")
		}

		expectedAudience, ok := ctx.Value(audienceContextKey).(string)
		if !ok {
			return status.Error(codes.Unauthenticated, "audience not provided in context")
		}

		if claims.Issuer != expectedIssuer {
			return status.Error(codes.Unauthenticated, "invalid issuer")
		}

		if !claims.Audience.Contains(expectedAudience) {
			return status.Error(codes.Unauthenticated, "invalid audience")
		}
	}
	return nil
}

