// normalizeUsername converts identifiers to canonical form for consistent regulation
func normalizeUsername(identifier string) string {
	// Trim leading/trailing whitespace
	normalized := strings.TrimSpace(identifier)

	// Convert to lowercase for case-insensitive handling
	normalized = strings.ToLower(normalized)

	// Extract username from email addresses (remove domain part)
	if idx := strings.Index(normalized, "@"); idx > 0 {
		normalized = normalized[:idx]
	}

	return normalized
}

