			if !allowed {
				return fmt.Errorf("command %q is not allowed", cmd)
			}
		}

		for _, cmd := range Config.Actions.ExecuteSync {
			allowed := false
			for _, allowedCmd := range Config.AllowedCommands {
				if cmd == allowedCmd {
