  if (!(node instanceof ObjectNode)) {
    throw new TypeError('No valid ObjectNode')
  }

  var entries = [];
  for (var key in node.properties) {
    if (hasOwnProperty(node.properties, key)) {
      if (!isSafeProperty(node.properties, key)) {
        throw new Error('No access to property "' + key + '"');
      }

      // Security: Normalize Unicode homoglyphs and check forbidden properties
      var normalizedKey = key.normalize('NFKC')
        .replace(/\u0441/g, 'c')  // Cyrillic 'с' to 'c'
        .replace(/[\u0300-\u036f]/g, '')  // Remove diacritics
        .toLowerCase();

      var forbiddenProperties = ['constructor', '__proto__', 'prototype'];
      if (forbiddenProperties.indexOf(normalizedKey) !== -1) {
        throw new Error('No access to property "' + key + '"')
      }

      entries.push(stringify(key) + ': ' + compile(node.properties[key], defs, args));
    }
  }
  return '{' + entries.join(', ') + '}';
}

