function compileObjectNode(node, defs, args) {
  if (!(node instanceof ObjectNode)) {
    throw new TypeError('No valid ObjectNode')
  }

  // Define comprehensive homoglyph mapping for forbidden property characters
  var homoglyphMap = {
    // c
    '\u0441': 'c', '\u03f2': 'c', '\u2ca5': 'c', '\uff43': 'c',
    // o
    '\u043e': 'o', '\u03bf': 'o', '\u0e4f': 'o', '\uff4f': 'o',
    // n
    '\u043d': 'n', '\u0578': 'n', '\uff4e': 'n',
    // s
    '\u0455': 's', '\uff53': 's',
    // t
    '\u0442': 't', '\u03c4': 't', '\uff54': 't',
    // r
    '\u0440': 'r', '\u03c1': 'r', '\uff52': 'r',
    // u
    '\u0443': 'u', '\u03c5': 'u', '\uff55': 'u',
    // e
    '\u0435': 'e', '\uff45': 'e',
    // p
    '\u03c0': 'p', '\u0e1f': 'p', '\uff50': 'p',
    // y
    '\u04af': 'y', '\uff59': 'y',
    // _ (underscore)
    '\u4e00': '_', '\uff3f': '_'
  };
  var forbiddenProperties = ['constructor', '__proto__', 'prototype'];

  var entries = [];
  for (var key in node.properties) {
    if (hasOwnProperty(node.properties, key)) {
      if (!isSafeProperty(node.properties, key)) {
        throw new Error('No access to property "' + key + '"')
      }

      // Canonicalize key: normalize, map homoglyphs, remove diacritics, lowercase
      var normalizedKey = typeof key.normalize === 'function' 
        ? key.normalize('NFKC') 
        : key;
      var asciiKey = '';
      for (var i = 0; i < normalizedKey.length; i++) {
        var char = normalizedKey[i];
        asciiKey += homoglyphMap[char] || char;
      }
      asciiKey = asciiKey.replace(/[\u0300-\u036f]/g, '').toLowerCase();

      // Explicitly check against forbidden properties
      if (forbiddenProperties.indexOf(asciiKey) !== -1) {
        throw new Error('No access to property "' + key + '"')
      }

      entries.push(stringify(key) + ': ' + compile(node.properties[key], defs, args))
    }
  }
  return '{' + entries.join(', ') + '}'
}

