function compileObjectNode(node, defs, args) {
  if (!(node instanceof ObjectNode)) {
    throw new TypeError('No valid ObjectNode')
  }

  var forbiddenProperties = ['constructor', '__proto__', 'prototype'];
  var entries = [];
  for (var key in node.properties) {
    if (hasOwnProperty(node.properties, key)) {
      // Normalize key to prevent Unicode homoglyph attacks
      var normalizedKey = typeof key.normalize === 'function' 
        ? key.normalize('NFKC') 
        : key;

      // Block forbidden properties in any Unicode form
      if (forbiddenProperties.indexOf(normalizedKey) !== -1) {
