module.exports = (env) => {
  const toReplace = Object.keys(env).filter((envVar) => {
    // https://github.com/semantic-release/semantic-release/issues/1558
    if (envVar === 'GOPRIVATE') {
      return false;
    }

    return /token|password|credential|secret|private/i.test(envVar) && size(env[envVar].trim()) >= SECRET_MIN_SIZE;
  });

  // Generate patterns for both raw and URL-encoded secrets
  const patternSet = new Set();
  for (const envVar of toReplace) {
    const rawValue = env[envVar];
    // Add raw version
    patternSet.add(escapeRegExp(rawValue));
    // Add URL-encoded version
    patternSet.add(escapeRegExp(encodeURIComponent(rawValue)));
