func PDFHasImage(path string) bool {
	cmd := exec.Command("pdffonts", "-l", "5", path)
	out, err := cmd.Output()
	if err != nil {
		log.Println(err)
		return false
	}

	// Process output directly in Go to avoid shell injection
	outputStr := string(out)
	lines := strings.Split(outputStr, "\n")

	// Skip header lines (first two lines)
	if len(lines) < 3 {
		return true
	}

	// Check if any font lines exist after header
	for i := 2; i < len(lines); i++ {
		line := strings.TrimSpace(lines[i])
		if line != "" {
			return false
		}
	}
	return true
}

