        const atIndex = url.indexOf('@');
        if (atIndex !== -1) {
            const colonIndex = url.indexOf(':', atIndex);
            if (colonIndex !== -1) {
                // Ensure no slashes between @ and :
                const slashIndex = url.substring(atIndex, colonIndex).indexOf('/');
                if (slashIndex === -1) {
                    isScp = true;
                    url = 'ssh://' + url.substring(0, colonIndex) + '/' + url.substring(colonIndex + 1);
                }
            }
        }
    }

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            }
        }
