const parseUrl = (url, normalize = false) => {

    // Constants
    const MAX_URL_LENGTH = 2048;

    if (typeof url !== "string" || !url.trim()) {
        const err = new Error("Invalid url.")
        err.subject_url = url
        throw err
    }

    // Validate URL length to prevent ReDoS
    if (url.length > MAX_URL_LENGTH) {
        throw new Error("input exceeds maximum length");
    }

    if (normalize) {
        if (typeof normalize !== "object") {
            normalize = {
                stripHash: false
            }
        }
        url = normalizeUrl(url, normalize)
    }

    const parsed = parsePath(url);

    // Handle git-ssh URLs without regex
    if (parsed.parse_failed && url.startsWith("git@")) {
        const firstColonIndex = url.indexOf(':');
        if (firstColonIndex !== -1) {
            const host = url.substring(4, firstColonIndex);
            const path = url.substring(firstColonIndex + 1);

            // Update parsed object
            parsed.protocols = ["ssh"];
            parsed.protocol = "ssh";
            parsed.resource = host;
            parsed.host = host;
            parsed.user = "git";
            parsed.pathname = `/${path.replace(/^[/]+/, '')}`; // Ensure single leading slash
            parsed.hash = '';
            parsed.search = '';
            parsed.query = {};
            parsed.href = url;
            parsed.parse_failed = false; // Mark as successfully parsed
        }
    } else if (parsed.parse_failed) {
        // If parsing failed and it's not a git-ssh URL, throw
        throw new Error("URL parsing failed");
    }

    // SSRF protection: Block loopback addresses
    if (parsed.host) {
        const host = parsed.host.toLowerCase();
        if (host === 'localhost' || host === '::1') {
            throw new Error("Access to loopback addresses is not allowed");
        }
        if (host.startsWith('127.')) {
            const parts = host.split('.');
            if (parts[0] === '127') {
                throw new Error("Access to loopback addresses is not allowed");
            }
        }
    }

    return parsed;
}

