func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)

		// Master password derivation - should be from secure configuration
		masterPassword := "secure_master_password_here"

		// Try to get encrypted secret from DB
		encryptedSecret, err := ds.Property(context.TODO()).Get(consts.JWTSecretKey)
		if err != nil || encryptedSecret == "" {
			// No existing secret - generate new secure secret
			newSecret := uuid.NewString()

			// Encrypt and store new secret
			encrypted, err := encryptSecret(newSecret, masterPassword)
			if err != nil {
				log.Error("Failed to encrypt JWT secret", err)
				return
			}

			// Store encrypted version in DB
			if err := ds.Property(context.TODO()).Put(consts.JWTSecretKey, encrypted); err != nil {
				log.Error("Failed to store encrypted JWT secret", err)
				return
			}

			Secret = []byte(newSecret)
		} else {
			// Decrypt existing secret
			decrypted, err := decryptSecret(encryptedSecret, masterPassword)
			if err != nil {
				log.Error("Failed to decrypt JWT secret", err)
				// Fallback to temporary secret
				log.Error("Using temporary JWT secret due to decryption failure")
				Secret = []byte(uuid.NewString())
			} else {
				Secret = []byte(decrypted)
			}
		}

		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
