func Init(ds model.DataStore) {
	once.Do(func() {
		log.Info("Setting Session Timeout", "value", conf.Server.SessionTimeout)

		// Define secure file path for JWT secret storage
		dataDir := conf.Server.DataPath
		if dataDir == "" {
			dataDir = "."
		}
		secretFile := filepath.Join(dataDir, "jwt_secret")

		// Try to read existing secret from secure file
		secretBytes, err := os.ReadFile(secretFile)
		if err != nil {
			if os.IsNotExist(err) {
				// Generate new secure secret
				newSecret := uuid.NewString()

				// Write to secure file with restricted permissions
				err = os.WriteFile(secretFile, []byte(newSecret), 0600)
				if err != nil {
					log.Error("Failed to write JWT secret file", "error", err)
					// Fallback to temporary secret
					log.Error("Using temporary JWT secret due to file write error")
					Secret = []byte(uuid.NewString())
				} else {
					Secret = []byte(newSecret)
				}
			} else {
				log.Error("Failed to read JWT secret file", "error", err)
				// Fallback to temporary secret
				log.Error("Using temporary JWT secret due to file read error")
				Secret = []byte(uuid.NewString())
			}
		} else {
			Secret = secretBytes
		}

		TokenAuth = jwtauth.New("HS256", Secret, nil)
	})
}

